// Step 3: Validate file extension, MIME type, and size constraints
const item = $input.first();
const driveMeta = item.json;
const fileName = (driveMeta.name || driveMeta.fileName || '').trim();
const extension = fileName.includes('.') ? fileName.split('.').pop().toLowerCase() : '';

const supportedExtensions = ['pdf', 'txt', 'md', 'markdown', 'text'];
const maxSizeBytes = 15 * 1024 * 1024; // 15MB maximum

const binaryProperty = item.binary?.data;
const actualSize = binaryProperty?.data ? Buffer.byteLength(binaryProperty.data, 'base64') : (driveMeta.size || 0);

let isValid = true;
let validationError = null;

if (!fileName) {
  isValid = false;
  validationError = 'Validation Error: File name is missing.';
} else if (!supportedExtensions.includes(extension)) {
  isValid = false;
  validationError = `Validation Error: Unsupported file format .${extension}. Only PDF, TXT, and Markdown files are supported.`;
} else if (actualSize > maxSizeBytes) {
  isValid = false;
  validationError = `Validation Error: File size (${Math.round(actualSize / 1024 / 1024 * 10) / 10}MB) exceeds the 15MB limit.`;
}

return [{
  json: Object.assign({}, driveMeta, {
    is_valid: isValid,
    validation_error: validationError,
    file_name: fileName,
    file_type: extension === 'markdown' ? 'md' : (extension === 'text' ? 'txt' : extension),
    file_size_bytes: actualSize
  }),
  binary: item.binary
}];

// Step 4 & 5: Extract file metadata, generate deterministic UUID, compute SHA-256 hash
const crypto = require('crypto');
const item = $input.first();
const json = item.json;
const binaryData = item.binary?.data?.data || '';

if (!binaryData) {
  throw new Error('Fatal: No binary payload available for hashing and transmission.');
}

const buffer = Buffer.from(binaryData, 'base64');
const sha256Hash = 'sha256:' + crypto.createHash('sha256').update(buffer).digest('hex');

// Generate deterministic UUID v4 structure from Google Drive fileId or name
const fileIdentifier = json.id || json.fileId || json.file_name;
const md5Hex = crypto.createHash('md5').update('gdrive:' + fileIdentifier).digest('hex');
const deterministicDocId = [
  md5Hex.substring(0, 8),
  md5Hex.substring(8, 12),
  '4' + md5Hex.substring(13, 16),
  '8' + md5Hex.substring(17, 20),
  md5Hex.substring(20, 32)
].join('-');

const mimeType = json.mimeType || item.binary?.data?.mimeType || (json.file_type === 'pdf' ? 'application/pdf' : 'text/plain');
const dataUri = `data:${mimeType};base64,${binaryData}`;

return [{
  json: {
    documentId: deterministicDocId,
    fileName: json.file_name,
    fileType: json.file_type,
    mimeType: mimeType,
    source: 'google-drive',
    fileUrl: dataUri,
    contentHash: sha256Hash,
    fileSize: buffer.length,
    googleDriveFileId: json.id || null,
    modifiedTime: json.modifiedTime || new Date().toISOString(),
    driveWebLink: json.webViewLink || `https://drive.google.com/file/d/${json.id}/view`
  }
}];

