// Format successful ingestion report
const response = $input.first().json;
const meta = $node['Extract Metadata & Compute SHA-256'].json;

return [{
  json: {
    success: true,
    status: response.status || 'INDEXED',
    documentId: meta.documentId,
    fileName: meta.fileName,
    fileSize: meta.fileSize,
    contentHash: meta.contentHash,
    googleDriveFileId: meta.googleDriveFileId,
    driveLink: meta.driveWebLink,
    message: response.message || 'Document successfully indexed into DocAnalyser Hybrid RAG',
    details: response.details || null,
    processedAt: new Date().toISOString()
  }
}];

// Format error report for failed backend ingestion
const response = $input.first().json;
const meta = $node['Extract Metadata & Compute SHA-256'].json;

return [{
  json: {
    success: false,
    status: response.status || 'FAILED',
    documentId: meta.documentId,
    fileName: meta.fileName,
    error: response.error || response.message || 'Ingestion rejected by Spring Boot gateway',
    googleDriveFileId: meta.googleDriveFileId,
    failedAt: new Date().toISOString()
  }
}];

// Format rejection report for invalid file format or size limits
const item = $input.first().json;

return [{
  json: {
    success: false,
    status: 'REJECTED',
    fileName: item.file_name || 'unknown',
    error: item.validation_error || 'File validation failed',
    fileSize: item.file_size_bytes || 0,
    rejectedAt: new Date().toISOString()
  }
}];
